//--|🠊 ArchiveMain.tsx 🠈|--\\
//--|🠋 Dependencies 🠋|--\\
import React, { useEffect, useState } from 'react';

//--|🠋 Components 🠋|--\\
import DivisionFullscreen from '../../../components/Division/fullscreen/Division.fullscreen';

//--|🠋 Elements 🠋|--\\
import FormElements from './elements/form-components/FormElements';
import MenuElements from './elements/menu-components/MenuElements';
import TimeElements from './elements/time-components/TimeElements';
import TableElements from './elements/table-components/TableElements';
import AsideElements from './elements/aside-components/AsideElements';
import LabelElements from './elements/label-components/LabelElements';
import FigureElements from './elements/figure-components/FigureElements';
import ButtonElements from './elements/button-components/ButtonElements';
import ArticleElements from './elements/article-components/ArticleElements';
import SectionElements from './elements/section-components/SectionElements';
import DivisionElements from './elements/division-components/DivisionElements';
import NavigationElements from './elements/navigation-components/NavigationElements';

//--|🠋 Functions 🠋|--\\
import { revertBlocks } from '../../../scripts/Main';
import { stripBrackets, checkScreen } from '../../../../scripts';

interface InfoProps {
  info: {
    blockName: '<main>' | string;
    labelName: '(default)' | string;
    pageName: '[components]' | string;
  };
}
function ArchiveMain({ info }: InfoProps) {
  const [getOrientation, setOrientation] = useState<'landscape' | 'portrait'>(
    window.matchMedia('(orientation: landscape)').matches ? 'landscape' : 'portrait',
  ); //--|🠈 Updates state when the orientation changes 🠈|--\\
  const pageName = stripBrackets(info.pageName, '[]') as 'components';
  const blockName = stripBrackets(info.blockName, '<>') as 'main';
  const labelName = stripBrackets(info.labelName, '()') as 'default';

  useEffect(() => {
    //--|🟨|--\\
    return checkScreen(setOrientation);
  }, [pageName, blockName, labelName]);

  let startingPreview = 3 as number;
  let blurName = 'obnubilate' as string;
  return (
    <main
      id={`${pageName}-${blockName}`}
      className={`${blurName} ${labelName}-${blockName}`}
      onMouseEnter={(event) => {
        revertBlocks(event.currentTarget, pageName); //--|🠈 Revert to Default 🠈|--\\
      }}
      onClick={(event) => {
        revertBlocks(event.currentTarget, pageName); //--|🠈 Mobile has no hover, so a tap reverts instead 🠈|--\\
      }}
    >
      <section className={`${blockName}-foreground`}>
        <DivisionFullscreen
          //--|🠊 <div class="elements-main_fullscreen-default"/> 🠈|--\\
          cases={{
            axis: '[y]',
            show: startingPreview as number,
            call: ComponentsElements as React.ComponentType<InfoProps>,
          }}
          info={{
            labelName: 'elements',
            blockName: blockName as '<main>',
            pageName: pageName as '[components]',
          }}
        />
      </section>
      <figure className={`${blockName}-midground`}></figure>
      <div className={`${blockName}-background`}></div>
    </main>
  );
}

const ComponentsElements: React.FC<InfoProps> = ({ info }) => {
  const blockName = info.blockName as 'main';
  const labelName = info.labelName as 'default';
  const pageName = info.pageName as 'components';

  return (
    <>
      <ArticleElements
        info={{
          pageName: pageName,
          blockName: blockName,
          labelName: 'article' as string,
        }}
      />
      <AsideElements
        info={{
          pageName: pageName,
          blockName: blockName,
          labelName: 'aside' as string,
        }}
      />
      <ButtonElements
        info={{
          pageName: pageName,
          blockName: blockName,
          labelName: 'button' as string,
        }}
      />
      <DivisionElements
        info={{
          pageName: pageName,
          blockName: blockName,
          labelName: 'division' as string,
        }}
      />
      <FigureElements
        info={{
          pageName: pageName,
          blockName: blockName,
          labelName: 'figure' as string,
        }}
      />
      <FormElements
        info={{
          pageName: pageName,
          blockName: blockName,
          labelName: 'form' as string,
        }}
      />
      <LabelElements
        info={{
          pageName: pageName,
          blockName: blockName,
          labelName: 'label' as string,
        }}
      />
      <MenuElements
        info={{
          pageName: pageName,
          blockName: blockName,
          labelName: 'menu' as string,
        }}
      />
      <NavigationElements
        info={{
          pageName: pageName,
          blockName: blockName,
          labelName: 'navigation' as string,
        }}
      />
      <SectionElements
        info={{
          pageName: pageName,
          blockName: blockName,
          labelName: 'section' as string,
        }}
      />
      <TableElements
        info={{
          pageName: pageName,
          blockName: blockName,
          labelName: 'table' as string,
        }}
      />
      <TimeElements
        info={{
          pageName: pageName,
          blockName: blockName,
          labelName: 'time' as string,
        }}
      />
    </>
  );
};
export default ArchiveMain;
